
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_sb98_2b_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_sb98_2b", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.337487936682912e+00, -3.273095854561376e+00, -3.182889345408711e+00, -3.057984377632582e+00, -2.887918607790680e+00, -2.661920174021084e+00, -2.371976802479339e+00, -2.018640032099495e+00, -1.619692084906201e+00, -1.215300032703958e+00, -8.344234199744054e-01, -5.770750682076106e-01, -5.007291016776668e-01, -4.133143118905847e-01, -2.977726145601750e-01, -1.857349029240479e-01, -1.102277126481200e-01, -4.983314160313301e-02, -1.212871061083012e-02, -1.450211290465897e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


